-- Stage 11b (3 of 5): business emails and phones onto a contact
-- Tom's choices from the review page (https://claude.ai/artifact/DLucB792pjaV87MDs4ufcm), 23 Oct 2026:
-- everything as suggested, except the Formers listed in supabase/.local/11b/choices.txt.
-- Generated by supabase/.local/11b/make_fix.py.
--
-- Adds the business's own email and phone to its main contact (or, with no named person, to its unnamed
-- "Contact" record) where no contact of the business has them: 138 businesses. The business keeps
-- its own copy. Left alone: 10 with no contact at all, and the 2 whose email is a person at another
-- business (HIMALAYAN SPRINGS, Jazz at the George IV).
-- Every row it changes is copied to cc_phase0_backup (reason 'stage11b_contacts_2026_10_24') first.
-- Undo: supabase/data-fixes/20261024_stage11b_3_contacts_undo.sql
-- Run with psql -v ON_ERROR_STOP=1 after migration 20261024_001_stage11b. It refuses to run twice.

BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cc_phase0_backup WHERE reason = 'stage11b_contacts_2026_10_24') THEN
    RAISE EXCEPTION 'stage11b_contacts_2026_10_24 has already been applied';
  END IF;
END $$;

CREATE TEMP TABLE _ct (biz uuid PRIMARY KEY, biz_name text NOT NULL, contact uuid NOT NULL, email text, phone text) ON COMMIT DROP;

-- every business still exists, is not merged away and has the name Tom saw
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad
  FROM _ct m LEFT JOIN businesses b ON b.id = m.biz
  WHERE b.id IS NULL OR b.name IS DISTINCT FROM m.biz_name OR b.merged_into IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'changed since the review: %', bad; END IF;
END $$;

DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(m.biz_name, ', ') INTO bad FROM _ct m LEFT JOIN contacts k ON k.id = m.contact
  WHERE k.id IS NULL OR k.business_id <> m.biz;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'contact moved or gone: %', bad; END IF;
END $$;

-- only what no contact of the business has yet
CREATE TEMP TABLE _add ON COMMIT DROP AS
SELECT m.contact,
  CASE WHEN m.email IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM contacts k, jsonb_array_elements_text(coalesce(k.emails, '[]')) e
    WHERE k.business_id = m.biz AND lower(btrim(e)) = lower(btrim(m.email))) THEN btrim(m.email) END AS email,
  CASE WHEN m.phone IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM contacts k, jsonb_array_elements_text(coalesce(k.phones, '[]')) p
    WHERE k.business_id = m.biz AND right(regexp_replace(p, '\D', '', 'g'), 10) = right(regexp_replace(m.phone, '\D', '', 'g'), 10)) THEN btrim(m.phone) END AS phone
FROM _ct m;
DELETE FROM _add WHERE email IS NULL AND phone IS NULL;

SELECT 'contacts', k.id, to_jsonb(k), 'stage11b_contacts_2026_10_24' FROM contacts k WHERE k.id IN (SELECT contact FROM _add);

UPDATE contacts k SET
  emails = CASE WHEN a.email IS NULL THEN k.emails ELSE coalesce(k.emails, '[]'::jsonb) || to_jsonb(a.email) END,
  phones = CASE WHEN a.phone IS NULL THEN k.phones ELSE coalesce(k.phones, '[]'::jsonb) || to_jsonb(a.phone) END
FROM _add a WHERE k.id = a.contact;

DO $$ BEGIN
  RAISE NOTICE 'stage 11b contacts: % contacts given % emails and % phones',
    (SELECT count(*) FROM _add), (SELECT count(email) FROM _add), (SELECT count(phone) FROM _add);
END $$;

COMMIT;
